426	            byte[] out = digest.digest(String.join(SEP, parts).getBytes(StandardCharsets.UTF_8));
427	            return HexFormat.of().formatHex(out);
428	        } catch (NoSuchAlgorithmException e) {
429	            throw new IllegalStateException(e);
430	        }
431	    }
432	
433	    private IncidentView toView(Incident incident, String pendingTransferTo) {
434	        return new IncidentView(incident.incidentKey(), incident.severity(), incident.summary(),
435	                incident.reporter(), incident.status().name(), incident.commander(), pendingTransferTo,
436	                incident.createdAt(), incident.updatedAt(), incident.deadlineAt());
437	    }
