18	 * 并支撑关键约束：事件键唯一、每事件至多一条升级记录、条件更新只作用于 OPEN。
19	 * 使用独立命名内存库，连接关闭即释放，不依赖外部数据库。
20	 */
21	class SchemaH2ScriptTest {
22	
23	    @Test
24	    void h2Schema_executesAndEnforcesConstraints() throws Exception {
25	        String url = "jdbc:h2:mem:schema_h2_check;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=0";
26	        try (Connection con = DriverManager.getConnection(url, "sa", "")) {
27	            ScriptUtils.executeSqlScript(con, new ClassPathResource("schema-h2.sql"));
28	
29	            Instant now = Instant.parse("2026-09-22T00:00:00Z");
30	            try (Statement st = con.createStatement()) {
31	                st.execute("INSERT INTO incidents (incident_key, severity, summary, reporter, status,"
32	                        + " commander, created_at, updated_at, deadline_at) VALUES"
33	                        + " ('IK-1','S1','s','r','COMMANDING','alice','" + Timestamp.from(now) + "',"
34	                        + "'" + Timestamp.from(now) + "','" + Timestamp.from(now.plusSeconds(300)) + "')");
35	
36	                // incident_key 唯一约束
37	                boolean duplicateRejected = false;
38	                try {
39	                    st.execute("INSERT INTO incidents (incident_key, severity, summary, reporter, status,"
40	                            + " commander, created_at, updated_at) VALUES"
41	                            + " ('IK-1','S1','s','r','REPORTED',NULL,'" + Timestamp.from(now) + "',"
42	                            + "'" + Timestamp.from(now) + "')");
43	                } catch (Exception e) {
44	                    duplicateRejected = true;
45	                }
46	                assertThat(duplicateRejected).isTrue();
47	
48	                st.execute("INSERT INTO incident_escalations (incident_id, deadline_at, triggered_at,"
49	                        + " triggered_commander, status, note, acknowledged_by, acknowledged_at,"
50	                        + " created_at, updated_at) VALUES (1,'" + Timestamp.from(now.plusSeconds(300))
51	                        + "','" + Timestamp.from(now) + "','alice','OPEN',NULL,NULL,NULL,'"
52	                        + Timestamp.from(now) + "','" + Timestamp.from(now) + "')");
53	
54	                // 每事件至多一条升级记录
55	                boolean secondEscalationRejected = false;
56	                try {
57	                    st.execute("INSERT INTO incident_escalations (incident_id, deadline_at,"
58	                            + " triggered_at, triggered_commander, status, note, acknowledged_by,"
59	                            + " acknowledged_at, created_at, updated_at) VALUES (1,'"
60	                            + Timestamp.from(now.plusSeconds(300)) + "','" + Timestamp.from(now)
61	                            + "','alice','OPEN',NULL,NULL,NULL,'" + Timestamp.from(now) + "','"
62	                            + Timestamp.from(now) + "')");
63	                } catch (Exception e) {
64	                    secondEscalationRejected = true;
65	                }
66	                assertThat(secondEscalationRejected).isTrue();
67	
68	                // 条件更新只作用于 OPEN：CANCELLED 后确认更新 0 行
69	                int cancelled = st.executeUpdate("UPDATE incident_escalations SET status='CANCELLED'"
70	                        + " WHERE incident_id = 1 AND status = 'OPEN'");
71	                assertThat(cancelled).isEqualTo(1);
72	                int lateAck = st.executeUpdate("UPDATE incident_escalations SET status='ACKNOWLEDGED'"
73	                        + " WHERE id = 1 AND status = 'OPEN'");
74	                assertThat(lateAck).isZero();
75	
76	                try (ResultSet rs = st.executeQuery(
77	                        "SELECT status, deadline_at FROM incident_escalations WHERE incident_id = 1")) {
78	                    assertThat(rs.next()).isTrue();
79	                    assertThat(rs.getString("status")).isEqualTo("CANCELLED");
80	                    assertThat(rs.getTimestamp("deadline_at").toInstant())
81	                            .isEqualTo(now.plusSeconds(300));
82	                }
83	            }
84	        }
85	    }
86	}
