        String c = reportAndTakeover("INC-C", "carol");
        taskService.createTask(a, "alice",
                new TaskCreateRequest(key(), "A1", "G", "等 B、C", List.of(b, c)));

        ApiException early = catchApi(() -> taskService.completeTask(a, "A1", "alice",
